typedef struct { const char *label; uint16_t offset; } PcScriptLabel;
/* A bg_event: the cell (x, y) answers to A. `kind` is the original's
 * BGEVENT_* type byte; READ, the four directional kinds, JUMPTEXT,
 * JUMPSTD and the hidden items have a script here ($ffff otherwise).
 * `flag` hides a hidden item once it has been taken ($ffff: none),
 * which is the test BGEVENT_ITEM does before it reads. */
typedef struct { uint8_t x, y, kind; uint16_t script;
    uint16_t flag; } PcBgEvent;
/* A coord_event: ending a step on (x, y) runs `script` while the map's
 * scene is `scene`, or from any scene when it is SCENE_ALWAYS (-1).
 * `script` is $ffff when the extractor could not find the label. */
typedef struct { uint8_t x, y; int8_t scene; uint16_t script;
    } PcCoordEvent;
/* `map_id` (GROUP_x, MAP_x): what setmapscene/checkmapscene put in a
 * script, and the only way to find another map's scene byte. `slot`
 * is the position in pc_script_maps. */
typedef struct { uint8_t group, number, slot; } PcSceneMap;
/* map_index is the position in pc_maps, so the game can find a map's
 * bytecode by the map it loaded. objects[] is one script offset per
 * object_event, bg[] one per bg_event, coords[] one per coord_event.
 * scene_count is the map's scene table size (0: it has none). */
typedef struct { const char *map; int8_t map_index; const uint8_t *bytes;
    uint16_t len; const PcScriptLabel *labels; uint16_t label_count;
    const uint16_t *objects; uint8_t object_count;
    const PcBgEvent *bg; uint8_t bg_count;
    const PcCoordEvent *coords; uint8_t coord_count;
    uint8_t scene_count; } PcScriptMap;

